class AdaptiveCapLaw(Contract):
    VERSION = 1

    # UNIMPLEMENTABLE: "We commit to report our intended catch before fishing and our actual catch after fishing, and to use the post-harvest discussion to adjust toward the cap above."
    # UNIMPLEMENTABLE: "This rule lasts for one month and is renewed only if at least 4 of 5 fishers agree."

    def __init__(self, num_agents, agent_names, *, prior_state=None):
        super().__init__(num_agents, agent_names, prior_state=prior_state)
        if prior_state is None:
            self.state["next_month_reduction"] = 0
        else:
            self.state.setdefault("next_month_reduction", 0)

    def on_round_start(self, month, fish_population, ctx) -> None:
        pass

    def resolve(self, month, fish_population, submissions, ctx) -> dict[str, float]:
        base_cap = 4.0
        if fish_population < 30.0:
            base_cap = 3.0

        reduction = float(self.state.get("next_month_reduction", 0))
        cap = max(1.0, base_cap - reduction)

        final_catches = {}
        for name in self.agent_names:
            submitted = float(submissions.get(name, 0.0))
            catch = min(submitted, cap)
            if catch < 0.0:
                catch = 0.0
            final_catches[name] = catch

            excess = max(0.0, submitted - cap)
            if excess > 0.0:
                penalty = 2000.0 * excess
                others = [n for n in self.agent_names if n != name]
                if others:
                    share = penalty / len(others)
                    for other in others:
                        ctx.transfer(name, other, share, reason="Penalty for exceeding harvest cap")

        return final_catches

    def on_round_end(self, month, fish_population_after, final_catches, ctx) -> None:
        if fish_population_after < 10.0:
            current_reduction = float(self.state.get("next_month_reduction", 0))
            self.state["next_month_reduction"] = current_reduction + 1.0
        else:
            self.state["next_month_reduction"] = 0.0
